CREATE TABLE app_settings (setting_key VARCHAR(80) PRIMARY KEY,value JSON NOT NULL,updated_by CHAR(32) NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(updated_by) REFERENCES users(id));
