CREATE TABLE rate_limits (bucket VARCHAR(190) PRIMARY KEY,window_start INT UNSIGNED NOT NULL,hits INT UNSIGNED NOT NULL);
ALTER TABLE conversations ADD visitor_token_hash CHAR(64) NULL, ADD property_id CHAR(32) NULL, ADD UNIQUE INDEX uq_visitor_token(visitor_token_hash), ADD FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE SET NULL;
